-- ************************************** DBT.DIM_CUSTOMER
CREATE VIEW DBT.DIM_CUSTOMER
(
  CUSTKEY COMMENT 'Unique identifier for the customer. Primary key of this dimension.',
  CUSTOMER_NAME COMMENT 'Customer''s full name, standardized to uppercase for consistent matching and display.',
  ADDRESS COMMENT 'Customer''s mailing address, trimmed of leading/trailing whitespace.',
  NATIONKEY COMMENT 'Foreign key referencing the nation the customer is associated with.',
  PHONE COMMENT 'Customer''s phone number with all non-numeric characters removed.',
  ACCOUNT_BALANCE COMMENT 'Customer''s account balance, rounded to 2 decimal places.',
  MARKET_SEGMENT COMMENT 'Market segment the customer belongs to (e.g. AUTOMOBILE, BUILDING, FURNITURE, MACHINERY, HOUSEHOLD).',
  COMMENT COMMENT 'Free-text comment field carried over from the source system.',
  LOAD_TIMESTAMP COMMENT 'Timestamp indicating when this record was loaded into the model.'
)
COMMENT = 'Customer dimension table, cleansed and standardized from the staging layer. Applies name casing, address trimming, phone normalization, and account balance rounding for downstream reporting and analytics.'
AS
WITH STG_CUSTOMER AS (
    SELECT
        CUSTKEY,
        NAME,
        ADDRESS,
        NATIONKEY,
        PHONE,
        ACCTBAL,
        MKTSEGMENT,
        COMMENT,
        LOAD_TIMESTAMP
    FROM DBT.DBT.STG_CUSTOMER
),

DIM_CUSTOMER AS (
    SELECT
        CUSTKEY,
        UPPER(NAME) AS CUSTOMER_NAME,
        TRIM(ADDRESS) AS ADDRESS,
        NATIONKEY,
        REGEXP_REPLACE(PHONE, '[^0-9]', '') AS PHONE,
        ROUND(ACCTBAL, 2) AS ACCOUNT_BALANCE,
        MKTSEGMENT AS MARKET_SEGMENT,
        COMMENT,
        CURRENT_TIMESTAMP AS LOAD_TIMESTAMP
    FROM STG_CUSTOMER
)
SELECT *
FROM DIM_CUSTOMER;

